  function exportPayload(){const droneProgress=Object.keys(DEFAULT.droneRecords).map(phase=>`Drone missão ${phase}: ${state.droneMedals[phase]||'sem medalha'}${state.droneRecords[phase]?` em ${state.droneRecords[phase].toFixed(2)}s`:''}`);return{text:['SIMULADORES INTERATIVOS DS — V4.15.0',`Créditos locais: ${state.bits}`,...Object.entries(GAMES).map(([id,game])=>`${game.name}: recorde ${state.best[id]||0}, vitórias ${state.wins[id]||0}`),...droneProgress,`Drone selecionado: ${droneModelConfig(state.droneModel).label}`,`Ambiente: ${droneEnvironmentConfig(state.droneEnvironment).label}`,`Clima: ${normalizeDroneWeatherMode(state.droneWeatherMode)}`,`Modo de voo: ${droneFlightModeConfig(state.droneFlightMode).label}`,`Layout de controle: ${droneControlModeConfig(state.droneControlMode).label}`,'Observação: Probabilidade e mercado utilizam dados fictícios; o voo de drone é uma simulação educacional.'].join('\n'),native:JSON.stringify(state,null,2),backup:state,meta:[{label:'Créditos',value:String(state.bits)},{label:'Medalhas Drone',value:String(Object.values(state.droneMedals).filter(Boolean).length)}]};}
  function help(){return'<h3>Simuladores Interativos DS V4.15.0</h3><p>O Drone exige montagem, inspeção, calibração de IMU, bússola, rádio e GPS antes de armar. Escolha Treinamento, Padrão, Esporte ou Manual; use layout simplificado, Modo 2 ou Modo 1; acompanhe bateria, rádio, satélites, distância, altura e velocidade. M alterna o modo de voo, G abre o pré-voo/armação, C troca câmera, X ativa precisão e R restaura o checkpoint. O sensor do celular para a câmera depende de HTTPS, permissão e hardware compatível. Esta é uma simulação educacional e não substitui treinamento prático, manual do fabricante ou legislação.</p>';}
